<div class="form-grid"><label>Màu nhấn<input type="color" wire:model="form.accent" /></label><label>Bố cục<select wire:model="form.layout"><option value="journal">Nhật ký</option><option value="journey">Hành trình</option><option value="magazine">Tạp chí</option></select></label></div><label>Tiêu đề hero<input wire:model="form.heading" maxlength="160" /></label><label>Mô tả hero<textarea wire:model="form.description" maxlength="1000"></textarea></label><label>Chân trang<input wire:model="form.footer" maxlength="300" /></label>
<p class="notice">Canvas cho phép thêm và sắp xếp section. Các trường hero phía trên dùng khi chưa có hero trên canvas. Trên điện thoại, ưu tiên chỉnh nội dung bằng form; canvas nâng cao phù hợp desktop.</p>
<div wire:ignore x-data x-init="$nextTick(() => { const mount = () => window.ButMayEditors.design($el, $wire, @js($form['project'] ?? [])); if(window.ButMayEditors) mount(); else window.addEventListener('butmay-editors-ready', mount, {once:true}); })"><div class="editor-toolbar"><button type="button" data-device="Desktop">Desktop</button><button type="button" data-device="Tablet">Tablet</button><button type="button" data-device="Mobile">Mobile</button></div><div data-grapes class="grapes-canvas"></div></div>
